#include <bits/stdc++.h>
using namespace std;

int main(void) {
	int n, k, m;
	int a[100], b[100];

	cin >> n >> k;
	for (int i = 0; i < n; i++)cin >> a[i];
	for (int i = 0; i < k; i++)cin >> b[i];

	m = -1;
	for (int i = 0; i < n; i++)m = max(m, a[i]);

	for (int i = 0; i < k; i++) {
		if (a[b[i] - 1] == m) {
			cout << "Yes" << endl;
			return 0;
		}
	}

	cout << "No" << endl;
	return 0;
}

n,k= map(int, input().split())
a= list(map(int, input().split()))
b= list(map(int, input().split()))

m=max(a)
flag=False

for i in range(k):
	if a[b[i]-1]==m:
		flag=True

if flag:
	print("Yes")
else:
	print("No")
